export function orbitCamera(B,scene,{name='camera',alpha=Math.PI/2,beta=.78,radius=29,target=[0,0,0],minRadius=12,maxRadius=43,minBeta=.3,maxBeta=1.38,fov=.78}={}){const camera=new B.ArcRotateCamera(name,alpha,beta,radius,new B.Vector3(...target),scene);Object.assign(camera,{minZ:.1,maxZ:150,lowerRadiusLimit:minRadius,upperRadiusLimit:maxRadius,lowerBetaLimit:minBeta,upperBetaLimit:maxBeta,fov});return{camera,reset(){camera.alpha=alpha;camera.beta=beta;camera.radius=radius;camera.target.set(...target);},zoom(delta){camera.radius=Math.max(minRadius,Math.min(maxRadius,camera.radius+delta));}};}
